import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1792300856000}`),a={name:`introduction.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h1><p>曦寒表单设计器（XiHan.FormDesigner）是一款框架无关的表单设计器：以原生 Web Components 交付，可视化编辑表单模板，在业务页面里按模板渲染出带排布、校验、联动、异步选项与列表录入的表单。属于曦寒懿（XiHanFun）开源生态，采用 MIT 授权。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to “能做什么”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>用什么</th></tr></thead><tbody><tr><td>设计与修改表单</td><td><code>&lt;xh-form-designer&gt;</code>：物料面板、拖放排布、属性与规则编辑、问题列表、复制粘贴、撤销重做，可切到预览态</td></tr><tr><td>在业务页面里填表</td><td><code>&lt;xh-form-renderer&gt;</code>：按模板渲染表单，取值、赋值、校验、重置与提交</td></tr><tr><td>不经界面处理表单数据</td><td><code>createFormController</code>：同一套取值、联动与校验，不碰 DOM</td></tr><tr><td>在服务端或脚本里检查</td><td><code>validateDocument</code> 检查模板，<code>validateValues</code> 按模板校验一份数据</td></tr></tbody></table><p>模板里能放的东西：</p><ul><li><strong>字段</strong>：单行与多行文本、可提及文本、密码、数字、验证码，下拉、可输入下拉、树选择、级联、单选组、多选组、按钮组、列表、可选标签、穿梭框、勾选框、开关，日期、日期范围、时间、时间范围，滑块、评分、颜色、标签、文件上传与签名。</li><li><strong>容器</strong>：栅格、标签页、卡片、折叠面板、分组与表格布局只管排版；子表单与子表的值是一组行，行可增删换序。</li><li><strong>静态元素</strong>：分隔线、段落、标题、提示、图片、条码与二维码，只展示、没有值。</li><li><strong>规则</strong>：校验（必填、必须勾选、长度、范围、正则、表达式）与联动（显示隐藏、启用禁用、必填与否、赋值），条件与取值都写成受限表达式。</li></ul><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to “设计原则”">​</a></h2><ul><li><strong>框架无关</strong>：以原生 Web Components 交付，不绑定任何前端框架。元素用 Light DOM，控件、样式与图标都来自 <a href="https://ui.docs.xihanfun.com" target="_blank" rel="noreferrer">XiHan.UI</a>，样式只消费它的设计令牌。</li><li><strong>零第三方依赖</strong>：运行时只依赖 <code>@xihan-form/*</code> 与 <code>@xihan-ui/*</code>，受限表达式与格式化也来自 XiHan.UI。</li><li><strong>模板即数据</strong>：模板是纯 JSON，不含也不执行任何代码。需要计算的地方用受限表达式，导入模板不会带来脚本注入。</li><li><strong>数据由使用方掌控</strong>：组件不发网络请求。模板存在哪里、选项从哪里取、附件传到哪里、谁能改模板，都由使用方决定，经属性、回调与事件交给组件。</li><li><strong>没有全局状态</strong>：不往 <code>window</code> 上挂对象，不读写固定键名的本地存储，同一页面放多个实例互不影响。</li><li><strong>按实例扩展</strong>：新的字段种类、属性编辑器、校验规则、命令与面板都写成扩展，经元素的 <code>extensions</code> 属性传入，只对这一个实例生效。</li></ul><h2 id="包与入口" tabindex="-1">包与入口 <a class="header-anchor" href="#包与入口" aria-label="Permalink to “包与入口”">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>内容</th></tr></thead><tbody><tr><td><code>@xihan-form/core</code></td><td>模板的类型定义、模板自检、取值校验、联动求值与编辑操作。纯 TypeScript，不依赖 DOM，浏览器与 Node.js 里都能用</td></tr><tr><td><code>@xihan-form/runtime</code></td><td>业务页面用的 <code>&lt;xh-form-renderer&gt;</code> 与表单控制器 <code>createFormController</code>，样式在 <code>@xihan-form/runtime/style.css</code></td></tr><tr><td><code>@xihan-form/runtime/locale</code></td><td>语言包，与 XiHan.UI 的内建语言一一对应（<code>formZhCN</code>、<code>formJaJP</code> 等），渲染器与设计器共用</td></tr><tr><td><code>@xihan-form/designer</code></td><td><code>&lt;xh-form-designer&gt;</code>，样式在 <code>@xihan-form/designer/style.css</code></td></tr></tbody></table><p>依赖方向固定为 <code>designer → runtime → core</code>。业务页面只需要 runtime，设计器只在需要编辑模板的地方加载。</p><h2 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to “工作流程”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设计器 &lt;xh-form-designer&gt;</span></span>
<span class="line"><span>  │  schema-change / save 事件</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>宿主保存模板 JSON（数据库、文件，由宿主决定）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>业务页面取模板与已有数据</span></span>
<span class="line"><span>  │  &lt;xh-form-renderer&gt;：选项加载、附件上传经回调交给宿主</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>submit 事件交出表单数据 ──▶ 宿主提交，服务端再用 validateValues 校验一遍</span></span></code></pre></div><ol><li>设计：在设计器里编辑模板，设计器派发 <code>schema-change</code> 与 <code>save</code>，宿主把模板 JSON 存起来。</li><li>填写：业务页面取出模板与已有数据交给 <code>&lt;xh-form-renderer&gt;</code>，下拉的选项、附件的上传经回调交给宿主。</li><li>提交：渲染器校验通过后派发 <code>submit</code>，宿主拿到表单数据自行提交；服务端可以用同一份模板再校验一遍。</li></ol><h2 id="运行环境" tabindex="-1">运行环境 <a class="header-anchor" href="#运行环境" aria-label="Permalink to “运行环境”">​</a></h2><ul><li><code>@xihan-form/core</code> 与 <code>createFormController</code> 不依赖 DOM，可以在浏览器、Node.js 或其它 JavaScript 运行环境里检查模板、校验数据。</li><li><code>&lt;xh-form-renderer&gt;</code> 与 <code>&lt;xh-form-designer&gt;</code> 要在支持 Custom Elements 的浏览器里运行。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./quickstart">快速开始</a>：在任意前端项目里装包、渲染一张表单并拿到提交的数据。</li><li><a href="./guide/template">模板结构</a>：字段、容器、布局与列表，以及表单数据的形状。</li><li><a href="./guide/validation">校验与联动</a>：校验规则、联动规则与表达式。</li><li><a href="./guide/renderer">渲染器</a>：取值与赋值、提交、选项加载、附件上传与只读禁用。</li><li><a href="./guide/designer">设计器</a>：编辑、属性与规则、预览、保存与命令排列。</li><li><a href="./guide/extensions">扩展</a>：新种类、渲染方式、规则、命令、面板与属性编辑器。</li><li><a href="./guide/host">与宿主集成</a>：模板的保存、权限、服务端复核与在前端框架里使用。</li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};